snippet_css:
:root{
  --bg: #F4ECD8;
  --fg: #2B2A28;
  --muted: #5B554A;
  --surface: #FFFFFF;
  --border: #2B2A28;
  --accent: #A34A17;
  --accent-fg: #FFFFFF;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 10px 24px rgba(43,42,40,.10);
  --btn-shadow: none;
  --art-bg: radial-gradient(circle at 30% 40%,#E1A624 0 18%,transparent 19%),radial-gradient(circle at 65% 55%,#2A8C8C 0 22%,transparent 23%),#F4ECD8;
  --media-bg: linear-gradient(150deg,#E1A624,#F4ECD8);
  --cta-bg: linear-gradient(180deg,#E1A624,#F4ECD8);
  --input-bg: #FFFDF6;
  --ok: #1E6B5E;
  --warn: #9B2C1F;
  --font-display: 'Josefin Sans','Noto Sans TC',sans-serif;
  --font-body: 'Work Sans','Noto Sans TC',sans-serif;
  --font-mono: ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

